function xpFitDesktopGrid() {
    if (!root.isContainment || !main.isRootView || main.sortMode !== -1
        || Plasmoid.containment.corona.editMode || dir.status !== Folder.FolderModel.Ready) return;
    const cols = Math.floor(gridView.width / gridView.cellWidth);
    const rows = Math.floor(gridView.height / gridView.cellHeight);
    if (cols < 1 || rows < 1) return;
    let layouts;
    try { layouts = JSON.parse(Plasmoid.configuration.positions || "{}"); } catch (e) { return; }
    const resolution = Plasmoid.configuration.lastResolution;
    const entries = layouts[resolution];
    if (!entries || (entries.length - 2) % 3 !== 0 || (entries.length - 2) / 3 > cols * rows) return;
    let occupied = new Set(), pending = [];
    for (let i = 2; i < entries.length; i += 3) {
        const x = Number(entries[i + 1]), y = Number(entries[i + 2]);
        if (!Number.isFinite(x) || !Number.isFinite(y)) return;
        if (x >= 0 && x < cols && y >= 0 && y < rows) occupied.add(x + "," + y);
        else pending.push(i);
    }
    if (pending.length === 0) return;
    let changed;
    try { changed = JSON.parse(Plasmoid.configuration.changedPositions || "{}"); } catch (e) { changed = {}; }
    for (const i of pending) {
        let x = Math.max(0, Math.min(cols - 1, Number(entries[i + 1])));
        let y = Math.max(0, Math.min(rows - 1, Number(entries[i + 2])));
        if (occupied.has(x + "," + y)) {
            let found = false;
            for (let xx = 0; xx < cols && !found; ++xx)
                for (let yy = 0; yy < rows && !found; ++yy)
                    if (!occupied.has(xx + "," + yy)) { x = xx; y = yy; found = true; }
            if (!found) return;
        }
        occupied.add(x + "," + y);
        entries[i + 1] = String(x); entries[i + 2] = String(y);
        changed[entries[i]] = [resolution, String(x), String(y)];
    }
    entries[0] = String(cols); entries[1] = String(rows);
    Plasmoid.configuration.positions = JSON.stringify(layouts);
    Plasmoid.configuration.changedPositions = JSON.stringify(changed);
}
